    sideMargin: 96,         // px kept clear on the left and right
    clearTop: 0.3, clearBottom: 0.8,      // vertical band the cloud may use (× section height): clear of the heading and the switch
    minTile: 0.1, maxTile: 0.17,  // tile edge × globe radius (a little smaller than before: more air between them)
