  const G = CONFIG.globe, ZB = 24;
  const DARKPAL = { '#0D1432': '#C9D1FF', '#3457BA': '#7B93FF', '#0C5238': '#3DCB8F' };   // midnight / blue / green lifted for a black background
  let PAL = [], PALW = G.palette.map(([, w]) => w), PALT = PALW.reduce((a, b) => a + b), PAPER = WHITE;
  const pickColor = () => { let r = rand() * PALT; for (let i = 0; i < PALW.length; i++) { r -= PALW[i]; if (r <= 0) return i; } return 0; };
  let PAL_CSS = [], OCEAN_CSS = [];
