  ul.innerHTML = LIST.map(([n, line, mk, label]) => { const p = PARTNERS.find((q) => q.name === n); if (!p) return '';
    const name = label || n, ink = p.ink && p.ink.toUpperCase() === '#000000' ? '#000' : '#fff';
    return `<li class="nl__row" style="--c:${p.bg};--k:${ink}"><div class="nl__wrap">
      <p class="nl__d"><span>${line}</span></p>
      <span class="nl__lg${mk ? ' mk' : ''}${n === 'WooCommerce' ? ' woo' : ''}"><svg viewBox="${p.mark.vb || '0 0 24 24'}" aria-hidden="true">${p.mark.body || `<path d="${p.mark.d}"/>`}</svg>${mk ? '' : `<b>${name}</b>`}</span>
      </div><a href="${p.href || '#'}" aria-label="${name}: ${line}"></a></li>`; }).join('');
  ul.querySelectorAll('.nl__lg.mk svg').forEach((sv) => { try { const b = sv.getBBox(); if (b.width) { sv.setAttribute('viewBox', `${b.x - .1} ${b.y - .1} ${b.width + .2} ${b.height + .2}`); sv.style.width = (b.width / b.height * parseFloat(getComputedStyle(sv).height)) + 'px'; } } catch (e) {} });
